// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 1e30);

        vm.deal(actor, amount);
        uint256 before = c.depositsCount();

        vm.prank(actor);
        // route Ether through the low-level call so the receive() fallback is triggered
        (bool ok, ) = address(c).call{value: amount}("");

        // General rule: every successful Ether deposit strictly increases the deposit counter.
        // The mutant decrements it, so it either reverts on underflow (ok == false) or the
        // counter does not grow — some fuzzed inputs break this.
        assertTrue(ok && c.depositsCount() > before);
    }
}
